                        ],
                        "otherRelevantDataCountries": [
                            "{{ISO_3166_ALPHA_2_CODE}}"
                        ]
                    },
                    "data": {
                        "Name": "Gas Chromatography",
                        "Description": "Gas chromatography (GC) is the process of separating compounds in a mixture by injecting a gaseous or liquid sample into a mobile phase, typically called the carrier gas, and passing the gas through a stationary phase. The mobile phase is usually an inert gas or unreactive gas such as helium, argon, nitrogen or hydrogen. The stationary phase is contained inside of a separation column. Today, most GC columns are fused silica capillaries with an inner diameter of 100-320 \u03bcm and a length of 5-60 m. The GC column is located inside an oven where the temperature of the gas can be controlled and the effluent coming off the column is monitored by a suitable detector as a function of retention time.",
                        "Code": "GasChromatography",
                        "Source": "Workbook Published/SampleAnalysisFamily.1.0.0.xlsx; commit SHA 4a76d5a5.",
                        "CommitDate": "2023-11-24T16:45:22+00:00"
                    }
                },
                {
                    "id": "{{NAMESPACE}}:reference-data--SampleAnalysisFamily:GasChromatographyMassSpectroscopy",
                    "kind": "osdu:wks:reference-data--SampleAnalysisFamily:1.0.0",
                    "acl": {
                        "owners": [
                            "{{DATA_OWNERS_GROUP}}"
                        ],
                        "viewers": [
                            "{{DATA_VIEWERS_GROUP}}"
                        ]
                    },
                    "legal": {
                        "legaltags": [
                            "{{LEGAL_TAG}}"
                        ],
                        "otherRelevantDataCountries": [
                            "{{ISO_3166_ALPHA_2_CODE}}"
                        ]
                    },
                    "data": {
                        "Name": "Gas Chromatography Mass Spectroscopy",
                        "Description": "GasChromatographyMassSpectroscopy (GCMS) is composed of two major building blocks: the gas chromatograph (GC) and the mass spectrometer (MS). The GC separates molecules in a mixture based on their relative affinity for the stationary phase of the column. Each GC peak elutes (comes off) from the column at different times (called the retention time), this allows the mass spectrometer downstream to capture, ionize, accelerate, deflect, and detect the ionized molecules separately. These two components, used together, allow a much finer degree of substance identification than than gas chromatography or mass spectrometry alone. ",
                        "Code": "GasChromatographyMassSpectroscopy",
                        "Source": "Workbook Published/SampleAnalysisFamily.1.0.0.xlsx; commit SHA 4a76d5a5.",
                        "CommitDate": "2023-11-24T16:45:22+00:00"
                    }
                },
                {
                    "id": "{{NAMESPACE}}:reference-data--SampleAnalysisFamily:GasChromatographyMassSpectroscopyMassSpectroscopy",
                    "kind": "osdu:wks:reference-data--SampleAnalysisFamily:1.0.0",
