                    "data": {
                        "Name": "Gas Chromatography Mass Spectroscopy Mass Spectroscopy",
                        "Description": "Gas Chromatography\u2013Tandem Mass spectrometry\u00a0(GC-MS-MS) couples a Gas Chromatograph (GC) with two Mass Spectrometers which increases detail in molecular structure analysis. This Family includes QQQ and MRM (Multiple-reaction Monitoring).\n",
                        "Code": "GasChromatographyMassSpectroscopyMassSpectroscopy",
                        "Source": "Workbook Published/SampleAnalysisFamily.1.0.0.xlsx; commit SHA 4a76d5a5.",
                        "CommitDate": "2023-11-24T16:45:22+00:00"
                    }
                },
                {
                    "id": "{{NAMESPACE}}:reference-data--SampleAnalysisFamily:Pyrolysis",
