                        ]
                    },
                    "data": {
                        "Name": "Pyrolysis",
                        "Description": "Pyrolysis is the thermal decomposition of materials at elevated temperatures, often in an inert atmosphere. In petroleum analysis, pyrolysis is the heating of an organic material, such as an oil or organic rich rock, in the absence of oxygen. Note that in practice, pyrolysis is sometimes used in combination with some other method to separate compounds. In OSDU, Pyrolysis (Py)-GC or PyGCMS are handled under the GC and GCMS analysis types. Bulk pyrolysis (e.g., RockEval) and kinetics measurements are grouped in this analysis type.",
                        "Code": "Pyrolysis",
                        "Source": "Workbook Published/SampleAnalysisFamily.1.0.0.xlsx; commit SHA 4a76d5a5.",
                        "CommitDate": "2023-11-24T16:45:22+00:00"
                    }
                },
                {
                    "id": "{{NAMESPACE}}:reference-data--SampleAnalysisFamily:RelativePermeability",
                    "kind": "osdu:wks:reference-data--SampleAnalysisFamily:1.0.0",
