                    "data": {
                        "Name": "Water Wash",
                        "ID": "WaterWash",
                        "Description": "Washing rock samples involves thorough rinsing with distilled water to remove loose particles, dust, and contaminants, often complemented by gentle scrubbing and, if necessary, ultrasonic or acid treatments.",
                        "Code": "WaterWash",
                        "Source": "Workbook ReferenceValues/Published/SamplePreparationMethod.1.xlsx; commit SHA 56f7c736.",
                        "CommitDate": "2024-02-09T16:51:15+00:00"
