                            "{{ISO_3166_ALPHA_2_CODE}}"
                        ]
                    },
                    "data": {
                        "Name": "Acid Wash",
                        "ID": "AcidWash",
                        "Description": "The acid wash involves immersing the rock sample in a dilute acid solution, such as hydrochloric acid, to dissolve and remove soluble minerals, followed by thorough rinsing with distilled water.",
                        "Code": "AcidWash",
                        "Source": "Workbook ReferenceValues/Published/SamplePreparationMethod.1.xlsx; commit SHA 56f7c736.",
                        "CommitDate": "2024-02-09T16:51:15+00:00"
                    }
